import { createScriptIdIframe } from '@util/script';
import status_bar_html from '../../界面/状态栏/index.html?raw';

const iframeAttribute = 'data-affinity-island-status-bar';

function mountStatusBar(message_id: number): void {
  const message = retrieveDisplayedMessage(message_id);
  if (!message.length || message.find(`[${iframeAttribute}]`).length) {
    return;
  }

  const placeholder = message.find('text[data-affinity-status-placeholder], [data-affinity-status-placeholder]');
  if (!placeholder.length) {
    return;
  }

  const iframe = createScriptIdIframe()
    .attr({
      [iframeAttribute]: 'true',
      title: '情感坐标状态栏',
      scrolling: 'no',
    })
    .css({
      display: 'block',
      width: '100%',
      minHeight: '70px',
      border: '0',
      background: 'transparent',
    })
    .on('load', function () {
      const document = this.contentDocument;
      if (!document) {
        return;
      }
      document.open();
      document.write(status_bar_html);
      document.close();
    });

  placeholder.replaceWith(iframe);
}

function mountLatestStatusBar(): void {
  const latest = getChatMessages(-1)[0];
  if (latest) {
    mountStatusBar(latest.message_id);
  }
}

$(() => {
  eventOn(tavern_events.CHARACTER_MESSAGE_RENDERED, mountStatusBar);
  eventOn(tavern_events.MESSAGE_UPDATED, mountStatusBar);
  eventOn(tavern_events.MESSAGE_RECEIVED, mountLatestStatusBar);
  eventOn(tavern_events.MESSAGE_SWIPED, mountLatestStatusBar);
  mountLatestStatusBar();
});
